CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING ((select auth.uid())=user_id);
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.contact_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,phone text NOT NULL DEFAULT '',services text NOT NULL DEFAULT '',budget text NOT NULL DEFAULT '',details text NOT NULL,package_id text,package_name text,package_price integer,package_billing text,status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','in_progress','closed')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.contact_submissions TO authenticated;
GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_inquiries ON public.contact_submissions FOR SELECT TO authenticated USING ((select public.has_role((select auth.uid()),'admin')));
CREATE POLICY admin_update_inquiries ON public.contact_submissions FOR UPDATE TO authenticated USING ((select public.has_role((select auth.uid()),'admin'))) WITH CHECK ((select public.has_role((select auth.uid()),'admin')));
CREATE INDEX contact_submissions_created_idx ON public.contact_submissions(created_at DESC);
CREATE TABLE public.chat_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),visitor_name text NOT NULL,visitor_email text NOT NULL,token_hash text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),last_message text NOT NULL DEFAULT '',last_sender text NOT NULL DEFAULT 'visitor',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.chat_conversations TO authenticated;
GRANT ALL ON public.chat_conversations TO service_role;
ALTER TABLE public.chat_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_chats ON public.chat_conversations FOR SELECT TO authenticated USING ((select public.has_role((select auth.uid()),'admin')));
CREATE POLICY admin_update_chats ON public.chat_conversations FOR UPDATE TO authenticated USING ((select public.has_role((select auth.uid()),'admin'))) WITH CHECK ((select public.has_role((select auth.uid()),'admin')));
CREATE INDEX chat_conversations_updated_idx ON public.chat_conversations(updated_at DESC);
CREATE TABLE public.chat_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES public.chat_conversations(id) ON DELETE CASCADE,sender text NOT NULL CHECK(sender IN ('visitor','admin')),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.chat_messages TO authenticated;
GRANT ALL ON public.chat_messages TO service_role;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_messages ON public.chat_messages FOR SELECT TO authenticated USING ((select public.has_role((select auth.uid()),'admin')));
CREATE POLICY admin_reply_messages ON public.chat_messages FOR INSERT TO authenticated WITH CHECK(sender='admin' AND (select public.has_role((select auth.uid()),'admin')));
CREATE INDEX chat_messages_conversation_idx ON public.chat_messages(conversation_id,created_at DESC);
CREATE FUNCTION public.update_chat_summary() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.chat_conversations SET last_message=left(NEW.body,180),last_sender=NEW.sender,updated_at=NEW.created_at,status='open' WHERE id=NEW.conversation_id; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.update_chat_summary() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER chat_summary AFTER INSERT ON public.chat_messages FOR EACH ROW EXECUTE FUNCTION public.update_chat_summary();
CREATE TABLE public.request_limits(key_hash text PRIMARY KEY,window_start timestamptz NOT NULL DEFAULT now(),hits integer NOT NULL DEFAULT 1);
GRANT ALL ON public.request_limits TO service_role;
ALTER TABLE public.request_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_request_limit(_key text,_max integer,_seconds integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result integer; BEGIN INSERT INTO public.request_limits(key_hash) VALUES(_key) ON CONFLICT(key_hash) DO UPDATE SET hits=CASE WHEN request_limits.window_start < now()-make_interval(secs=>_seconds) THEN 1 ELSE request_limits.hits+1 END,window_start=CASE WHEN request_limits.window_start < now()-make_interval(secs=>_seconds) THEN now() ELSE request_limits.window_start END RETURNING hits INTO result; RETURN result<=_max; END $$;
REVOKE EXECUTE ON FUNCTION public.consume_request_limit(text,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_request_limit(text,integer,integer) TO service_role;